<div class="section-toolbar"><div class="tabs"><a href="<?= e(url('inquiries')) ?>" class="<?= empty($_GET['status']) ? 'active' : '' ?>">All inquiries</a><?php foreach (['Pending', 'In Progress', 'Resolved', 'Cancelled'] as $status): ?><a href="<?= e(url('inquiries', ['status' => $status])) ?>" class="<?= ($_GET['status'] ?? '') === $status ? 'active' : '' ?>"><?= e($status) ?></a><?php endforeach; ?></div><a class="button primary" href="<?= e(url('inquiry-new')) ?>">+ Record inquiry</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Vehicle</th><th>Inquiry</th><th>Date / Recorded by</th><th>Status</th><th class="align-right">Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td class="strong"><?= e($row['Customer_Name']) ?><small><?= e($row['Contact_Number']) ?></small></td><td><a class="text-link" href="<?= e(url('vehicle', ['id' => $row['Vehicle_ID']])) ?>"><?= e($row['Brand_Name'] . ' ' . $row['Model']) ?></a></td><td class="wrap-cell"><span class="inquiry-excerpt"><?= e(mb_strimwidth($row['Inquiry_Message'], 0, 120, '…')) ?></span></td><td class="nowrap"><?= e(date('M j, Y', strtotime($row['Inquiry_Date']))) ?><small><?= e($row['Employee_Name'] ?: '—') ?></small></td><td><?= badge($row['Inquiry_Status']) ?></td><td><div class="row-actions"><a href="<?= e(url('inquiry-edit', ['id' => $row['Inquiry_ID']])) ?>">View / Edit</a></div></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6"><div class="empty-state"><span class="empty-icon" aria-hidden="true">▤</span><h3>No inquiries here yet</h3><p>Record a customer’s question and track it through to resolution.</p><a class="button primary" href="<?= e(url('inquiry-new')) ?>">+ Record inquiry</a></div></td></tr><?php endif; ?></tbody></table></div><?php $route = 'inquiries'; require __DIR__ . '/partials/pagination.php'; ?></section>
